mapper.select:
select *
from img_search_image
where instance_id = #{instanceId}
  and image_id = #{imageId}
limit 1

select *
from img_search_image
where instance_id = #{instanceId}
  and product_id = #{productId}
  and pic_name = #{picName}
limit 1

select *
from img_search_image
where instance_id = #{instanceId}
  and id > #{lastId}
  and id <= #{snapshotMaxId}
  and deleted = 0
  and indexable_flag = 1
order by id asc
limit #{limitSize}
